def copia_punto_in_punti(apps, schema_editor):
    """Le righe già inserite con un solo punto lo conservano fra i punti."""
    RigaProgramma = apps.get_model("assemblee", "RigaProgramma")
    for riga in RigaProgramma.objects.filter(punto__isnull=False):
        riga.punti.add(riga.punto_id)


def copia_punti_in_punto(apps, schema_editor):
    """All'indietro resta il primo punto per numero."""
    RigaProgramma = apps.get_model("assemblee", "RigaProgramma")
    for riga in RigaProgramma.objects.all():
        primo = riga.punti.order_by("ordine").first()
        if primo is not None:
            riga.punto = primo
            riga.save(update_fields=["punto"])


